const item = $input.first().json;
const headers = item.headers ?? {};
const body = item.body && typeof item.body === 'object' ? item.body : item;
const header = (name) => String(headers[name] ?? headers[name.toLowerCase()] ?? headers[name.toUpperCase()] ?? '').trim();
const text = (value) => typeof value === 'string' && value.trim() ? value.trim() : '';
const expectedSecret = String($env.N8N_WEBHOOK_SECRET ?? '').trim();
const errors = [];
if (item.httpMethod && String(item.httpMethod).toUpperCase() !== 'POST') errors.push('Invalid request method.');
if (header('x-zion-source') !== 'backend') errors.push('Invalid source.');
if (!expectedSecret || header('x-zion-workflow-secret') !== expectedSecret) errors.push('Invalid workflow secret.');
if (header('x-zion-event') !== 'booking.created') errors.push('Invalid event.');
if (!text(body.booking_id)) errors.push('Missing booking_id.');
if (!text(body.booking_reference)) errors.push('Missing booking_reference.');
if (!body.categorization || typeof body.categorization !== 'object' || !text(body.categorization.taskTemplateKey)) errors.push('Missing categorization.taskTemplateKey.');
if (header('x-zion-idempotency-key') && header('x-zion-idempotency-key') !== text(body.booking_reference)) errors.push('Invalid idempotency key.');
return [{ json: { authorized: errors.length === 0, errors, booking: { booking_id: text(body.booking_id), booking_reference: text(body.booking_reference), event_type: text(body.event_type) }, categorization: body.categorization ?? {}, workflow: { name: 'Zion - New Booking Orchestration', executionId: String($execution.id), triggeredAt: text(body.triggered_at) || new Date().toISOString() } } }];

const payload = $input.first().json;
if (payload.success !== true || !payload.booking) throw new Error(payload.message || 'Backend booking details response was not successful.');
const booking = payload.booking;
const categorization = payload.categorization ?? $('02. Validate Zion Booking Request').first().json.categorization ?? {};
const eventTime = [booking.start_time, booking.end_time].filter(Boolean).join(' - ') || 'To be confirmed';
return [{ json: { booking, categorization, summary: { bookingReference: booking.booking_reference, clientName: booking.client_name, clientEmail: booking.client_email, eventType: booking.event_type, eventDate: booking.event_date, eventTime, packageName: booking.package_name, guestCount: Number(booking.guest_count) || 0, riskLevel: categorization.riskLevel || 'medium', taskTemplateKey: categorization.taskTemplateKey || 'general_event_standard' }, workflow: { name: 'Zion - New Booking Orchestration', executionId: String($execution.id) } } }];

const source = $('05. Create Structured Booking Summary').first().json;
const booking = source.booking;
const categorization = source.categorization ?? {};
const templateKey = categorization.taskTemplateKey || 'general_event_standard';
const due = (days) => new Date(Date.now() + days * 86400000).toISOString();
const mk = (title, category, priority = 'medium', dueOffset = 1) => ({ title, category, priority, dueOffset });
const base = [mk('Review submitted booking details', 'booking_review', 'high', 1), mk('Verify event date and schedule availability', 'schedule_review', 'high', 1), mk('Confirm selected package inclusions', 'package_review', 'medium', 2), mk('Check payment and down payment requirements', 'payment_review', 'medium', 2), mk('Prepare client confirmation requirements', 'client_confirmation', 'medium', 3)];
const additions = { wedding_standard: [mk('Coordinate ceremony/reception requirements', 'event_requirements'), mk('Confirm motif, layout, and styling details', 'styling'), mk('Prepare supplier coordination checklist', 'supplier_coordination'), mk('Confirm food, guest count, and program timeline', 'program_food'), mk('Prepare final event coordination checklist', 'final_coordination')], birthday_debut_standard: [mk('Confirm theme and program flow', 'program_flow'), mk('Review setup, decorations, and stage requirements', 'styling'), mk('Confirm food and guest count', 'program_food'), mk('Prepare event host/program coordination checklist', 'program_coordination'), mk('Prepare final event coordination checklist', 'final_coordination')], christening_standard: [mk('Confirm ceremony and reception schedule', 'event_requirements'), mk('Review family/guest seating needs', 'seating'), mk('Confirm food and guest count', 'program_food'), mk('Prepare styling and setup requirements', 'styling'), mk('Prepare final event coordination checklist', 'final_coordination')], corporate_group_standard: [mk('Confirm company/group event requirements', 'event_requirements'), mk('Review technical needs such as sound, projector, and program flow', 'technical_requirements'), mk('Confirm food and guest count', 'program_food'), mk('Prepare logistics and supplier coordination checklist', 'supplier_coordination'), mk('Prepare final event coordination checklist', 'final_coordination')], general_event_standard: [mk('Confirm event requirements', 'event_requirements'), mk('Review setup and package inclusions', 'package_review'), mk('Confirm food and guest count', 'program_food'), mk('Prepare logistics checklist', 'logistics'), mk('Prepare final event coordination checklist', 'final_coordination')] };
const selected = additions[templateKey] || additions.general_event_standard;
const tasks = [...base, ...selected].map((task, index) => ({ orderIndex: index + 1, title: task.title, description: `${task.title} for booking ${booking.booking_reference}.`, priority: task.priority, status: 'pending', activationStatus: 'pending_booking_approval', isActive: false, isEditable: true, category: task.category, dueDate: due(task.dueOffset), assignedToRole: 'ADMIN', taskTemplateKey: templateKey }));
return [{ json: { relatedModule: 'booking', relatedRecordId: booking.booking_id, bookingReference: booking.booking_reference, source: 'n8n_workflow', workflowName: 'Zion - New Booking Orchestration', workflowExecutionId: String($execution.id), eventType: booking.event_type, clientName: booking.client_name, categorization, tasks } }];

const taskPayload = $('11A. Generate Admin To-Do List').first().json;
const saveResult = $input.first().json;
const createdCount = saveResult.data?.createdCount ?? saveResult.createdCount ?? taskPayload.tasks.length;
return [{ json: { type: 'NEW_BOOKING_TASK_LIST_CREATED', priority: 'HIGH', title: `New booking received: ${taskPayload.bookingReference}`, message: `A new ${taskPayload.eventType} booking was submitted. The admin To-Do list has been generated and is waiting for booking approval.`, relatedModule: 'BOOKING', relatedRecordId: taskPayload.relatedRecordId, bookingReference: taskPayload.bookingReference, audience: ['SUPERADMIN', 'ADMIN'], payload: { bookingSummary: { bookingReference: taskPayload.bookingReference, clientName: taskPayload.clientName, eventType: taskPayload.eventType }, categorization: taskPayload.categorization, taskCount: createdCount, tasksPreview: taskPayload.tasks.slice(0, 5).map((task) => ({ orderIndex: task.orderIndex, title: task.title, category: task.category })) } } }];
